import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_activations_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <math.h>

__device__ float gelu(float x) {
    return x * 0.5f * (1.0f + erff(x / 1.41421356237f));
}

__global__ void fused_activations_kernel(
    const float* input,
    const float* bias,
    float* output,
    int num_elements,
    int channels,
    int elements_per_channel
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= num_elements) return;

    int channel_idx = (idx / elements_per_channel) % channels;
    float x = input[idx];

    // Activation sequence
    x = fmaxf(0.0f, x);                     // ReLU
    x = fmaxf(0.01f * x, x);                // LeakyReLU
    x = gelu(x);                            // GELU
    x = 1.0f / (1.0f + expf(-x));           // Sigmoid
    x += bias[channel_idx];                 // Bias addition

    output[idx] = x;
}

torch::Tensor fused_activations_cuda(
    torch::Tensor input,
    torch::Tensor bias,
    int B, int C, int D, int H, int W
) {
    int num_elements = input.numel();
    int elements_per_channel = D * H * W;

    auto output = torch::empty_like(input);
    const int block_size = 256;
    int grid_size = (num_elements + block_size - 1) / block_size;

    fused_activations_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        num_elements,
        C,
        elements_per_channel
    );

    return output;
}
"""

fused_activations_cpp = "torch::Tensor fused_activations_cuda(torch::Tensor input, torch::Tensor bias, int B, int C, int D, int H, int W);"

fused_ops = load_inline(
    name="fused_ops",
    cpp_sources=fused_activations_cpp,
    cuda_sources=fused_activations_source,
    functions=["fused_activations_cuda"],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, bias_shape):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv3d(in_channels, out_channels, kernel_size)
        self.bias = nn.Parameter(torch.randn(bias_shape))

    def forward(self, x):
        x = self.conv(x)
        B, C, D, H, W = x.shape
        return fused_ops.fused_activations_cuda(x, self.bias, B, C, D, H, W)
